HOSTS = {
    ("gcs", False): "img-gcp.example.com",          # Cloud CDN → Cloud Run → GCS
    ("gcs", True):  "img-gcs-via-aws.example.com",  # CloudFront → Lambda@Edge → GCS
    ("s3",  False): "img-aws.example.com",
    ("s3",  True):  "img-s3-via-gcp.example.com",
}
FLAGS = {"gcp_cdn_down": False, "aws_cdn_down": False}

def image_url(meta, w):
    down = FLAGS["gcp_cdn_down"] if meta["bucket"] == "gcs" else FLAGS["aws_cdn_down"]
    return f"https://{HOSTS[(meta['bucket'], down)]}/{meta['key']}?w={w}"

img = {"id": 42, "bucket": "gcs", "key": "article/42.jpg"}
print(image_url(img, 360))   # https://img-gcp.example.com/article/42.jpg?w=360
FLAGS["gcp_cdn_down"] = True
print(image_url(img, 360))   # https://img-gcs-via-aws.example.com/article/42.jpg?w=360
